import { useEffect, useState } from 'react';
import axios from '../api/axios';
import { FaUser, FaEnvelope, FaUserShield, FaExclamationTriangle } from 'react-icons/fa';

function Profile() {
  const [user, setUser] = useState(null);
  const [message, setMessage] = useState('');

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token');

      if (!token) {
        setMessage('🔒 You are not logged in.');
        return;
      }

      try {
        const res = await axios.get('/profile', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        setUser(res.data);
      } catch (err) {
        console.error('Profile fetch error:', err);
        setMessage('⚠️ Failed to fetch profile. Please log in again.');
        localStorage.removeItem('token');
      }
    };

    fetchProfile();
  }, []);

  return (
    <div className="container py-5 text-white">
      <div className="bg-dark bg-opacity-75 p-4 rounded shadow">
        <h2 className="text-center mb-4">👤 Your Profile</h2>

        {message && (
          <div className="alert alert-warning bg-warning text-dark d-flex align-items-center">
            <FaExclamationTriangle className="me-2" />
            {message}
          </div>
        )}

        {user ? (
          <div className="card bg-light text-dark p-3 shadow">
            <p>
              <FaUser className="me-2 text-primary" />
              <strong>Name:</strong> {user.name}
            </p>
            <p>
              <FaEnvelope className="me-2 text-secondary" />
              <strong>Email:</strong> {user.email}
            </p>
            <p>
              <FaUserShield className="me-2 text-success" />
              <strong>Role:</strong> {user.role}
            </p>
          </div>
        ) : (
          !message && <p className="text-center">⏳ Loading your profile...</p>
        )}
      </div>
    </div>
  );
}

export default Profile;
